import torch, numpy as np
d = np.load('/work/d_rep_pre.npy').astype(np.float32)
writer_names = []
for L in range(24):
    writer_names.append(f'model.language_model.layers.{L}.mlp.down_proj.weight')
for L in [3,7,11,15,19,23]:
    writer_names.append(f'model.language_model.layers.{L}.self_attn.o_proj.weight')
for L in range(24):
    if L not in [3,7,11,15,19,23]:
        writer_names.append(f'model.language_model.layers.{L}.linear_attn.out_proj.weight')
for name in writer_names:
    W = load(name).numpy().astype(np.float32)
    W = W - np.outer(d, d @ W)
    save_edit(name, torch.from_numpy(W).float())
print('saved B2')

